def name_operands(region,function_address,operation):
    if (region,function_address)!=('Action',0xE9C2):return operation
    return (operation.replace('(#E9E7)','(@ActionNearestCandidateState.ClosestHigh)')
            .replace('(#E9FE)','(@ActionNearestCandidateState.ChosenIndex)')
            .replace('LD HL, #A01B','LD HL, @ActionCandidateListData.Slot00.Code - 1')
            .replace('CP #FE','CP @ActionCandidateListConst.ListEnd')
            .replace('LD (HL), #FF','LD (HL), @ActionCandidateListConst.SkippedIndex')
            .replace('CALL #E6A7','CALL @Action.RecordIndexToAddress.Entry')
            .replace('CALL #EAE9','CALL @Action.MaxRecordDeltaHigh.Entry'))


def qualify_mutations(records,flow,functions,pieces):
    for item in records:
        if item['region']=='Action' and item['writer'] in (0xE9C4,0xE9EA,0xE9F0):
            item.update(writer_slot=17,writer_offset=item['writer']-0x6000,writer_bank=0,
                target_slot=17,target_offset=item['target']-0x6000,target_bank=0,target_region='Action',
                target_path='Source/Action/FindNearestListedRecord.asm',target_source_classified=True,writer_source_classified=True)
